// --- Marshal (persist fields) ---

// CaptureRollbackState is side-effect free and includes transient and
// sync-only fields. Persistence changes live in RollbackTx, not in the DAO.
func (d *HeroDao) CaptureRollbackState() ([]byte, error) {
	return bson.Marshal(d.rollbackDoc())
}

func (d *HeroDao) RestoreRollbackState(raw []byte) error {
	var doc heroDaoRollbackDoc
	if err := bson.Unmarshal(raw, &doc); err != nil {
		return err
	}
	d.setPersistDoc(doc.PersistDoc)
	d.Init()
	return nil
}

// heroDaoRollbackDoc is the in-memory rollback snapshot, never stored:
// the persisted document plus the fields that are not persisted, under their
// keys.
type heroDaoRollbackDoc struct {
	PersistDoc heroDaoPersistDoc `bson:"_persisted"`
}

func (d *HeroDao) rollbackDoc() heroDaoRollbackDoc {
	return heroDaoRollbackDoc{
		PersistDoc: d.persistDoc(),
	}
}

// persistDoc is the full document of the current state; setPersistDoc puts a
// decoded one back (identity and persisted fields; the caller runs Init).
func (d *HeroDao) persistDoc() heroDaoPersistDoc {
	return heroDaoPersistDoc{
		ID:            d.id,
		SchemaVersion: HeroDaoSchemaVersion,
		Name:          d.name,
		Level:         d.level,
		Exp:           d.exp,
		LoginAt:       d.loginAt,
		Items:         d.heroDaoItemsRawMap(),
		Friends:       d.friends,
		Pos:           d.pos.bsonDoc(),
		Equips:        daoMapDocs(d.heroDaoEquipsRawMap(), equipInfoPtrBSONDoc),
		Squad:         daoSliceDocs(d.squad, equipInfoPtrBSONDoc),
		Mount:         equipInfoPtrBSONDoc(d.mount),
	}
}

func (d *HeroDao) setPersistDoc(doc heroDaoPersistDoc) {
	d.id = doc.ID
	d.name = doc.Name
	d.level = doc.Level
	d.exp = doc.Exp
	d.loginAt = doc.LoginAt
	d.setItemsRawMap(doc.Items)
	d.friends = doc.Friends
	d.pos = positionFromBSONDoc(doc.Pos)
	d.setEquipsRawMap(daoMapDocs(doc.Equips, equipInfoPtrFromBSONDoc))
	d.squad = daoSliceDocs(doc.Squad, equipInfoPtrFromBSONDoc)
	d.mount = equipInfoPtrFromBSONDoc(doc.Mount)
}

func (d *HeroDao) marshalCommitState() ([]byte, error) {
	return bson.Marshal(d.persistDoc())
}

func (d *HeroDao) PrepareMutation(change nest.PersistChange) (dataengine.Mutation, error) {
	version := d.tracker.Version()
	mutation := dataengine.Mutation{
		Key: dataengine.DocumentKey{
			Database: d.DbName(), Scope: dataengine.DatabaseScope(d.DbScope()),
			Resource: d.CollName(), ID: d.Id(),
		},
		Kind: dataengine.MutationPatch, ExpectedVersion: version, NextVersion: version + 1,
		Mask: change.Mask, Schema: HeroDaoSchemaVersion, Codec: "bson-v2",
	}
	if change.Delete {
		mutation.Kind = dataengine.MutationDelete
		return mutation, nil
	}
	if version == 0 || change.Mask == dataengine.AllFields {
		data, err := d.marshalCommitState()
		if err != nil {
			return dataengine.Mutation{}, fmt.Errorf("prepare put %s/%d: %w", d.CollName(), d.id, err)
		}
		mutation.Kind = dataengine.MutationPut
		mutation.Data = data
		return mutation, nil
	}
	patch, err := d.marshalPersistPatchBSON(change)
	if err != nil {
		return dataengine.Mutation{}, fmt.Errorf("prepare patch %s/%d: %w", d.CollName(), d.id, err)
	}
	mutation.Patch = patch
	return mutation, nil
}

func (d *HeroDao) AcceptMutation(mutation dataengine.Mutation) error {
	return d.tracker.AcceptVersion(mutation.ExpectedVersion, mutation.NextVersion)
}

func (d *HeroDao) Marshal() []byte {
	return d.MarshalPersist(dataengine.AllFields)
}

func (d *HeroDao) MarshalPersist(mask uint64) []byte {
	return d.marshalPersistData(mask)
}

func (d *HeroDao) marshalPersistData(mask uint64) []byte {
	_ = mask // full payload is used for inserts and safe fallback.
	data, err := d.marshalCommitState()
	if err != nil {
		// The interface has no error slot and a nil payload would be
		// persisted as silent data loss; a marshal failure here is a
		// programming error (unserializable state), so fail loudly and let
		// Data Engine WAL recovery owns the aftermath.
		panic(fmt.Errorf("HeroDao: marshal persist data: %w", err))
	}
	return data
}

func (d *HeroDao) persistChangeHasPath(change nest.PersistChange, field string) bool {
	prefix := field + "."
	for path := range change.Set {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	for _, path := range change.Unset {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *HeroDao) persistChangePathCovered(change nest.PersistChange, path string) bool {
	if change.FullMask&heroDaoFieldName != 0 && (path == "name" || strings.HasPrefix(path, "name.")) {
		return true
	}
	if change.FullMask&heroDaoFieldLevel != 0 && (path == "level" || strings.HasPrefix(path, "level.")) {
		return true
	}
	if change.FullMask&heroDaoFieldExp != 0 && (path == "exp" || strings.HasPrefix(path, "exp.")) {
		return true
	}
	if change.FullMask&heroDaoFieldLoginAt != 0 && (path == "login_at" || strings.HasPrefix(path, "login_at.")) {
		return true
	}
	if change.FullMask&heroDaoFieldItems != 0 && (path == "items" || strings.HasPrefix(path, "items.")) {
		return true
	}
	if change.FullMask&heroDaoFieldFriends != 0 && (path == "friends" || strings.HasPrefix(path, "friends.")) {
		return true
	}
	if change.FullMask&heroDaoFieldPos != 0 && (path == "pos" || strings.HasPrefix(path, "pos.")) {
		return true
	}
	if change.FullMask&heroDaoFieldEquips != 0 && (path == "equips" || strings.HasPrefix(path, "equips.")) {
		return true
	}
	if change.FullMask&heroDaoFieldSquad != 0 && (path == "squad" || strings.HasPrefix(path, "squad.")) {
		return true
	}
	if change.FullMask&heroDaoFieldMount != 0 && (path == "mount" || strings.HasPrefix(path, "mount.")) {
		return true
	}
	for field := range change.FullFields {
		prefix := field + "."
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *HeroDao) marshalPersistPatchBSON(change nest.PersistChange) (dataengine.FieldPatch, error) {
	set := make(map[string]any, len(change.Set)+len(change.FullFields))
	var unset []string
	for _, path := range change.Unset {
		if !d.persistChangePathCovered(change, path) {
			unset = append(unset, path)
		}
	}
	root := change.Paths.Root()
	if change.Mask&heroDaoFieldName != 0 {
		node := root.Child(dataengine.SyncStep{Field: 2})
		_, full := change.FullFields["name"]
		full = full || change.FullMask&heroDaoFieldName != 0
		if !root.Full() && node != nil && !full {
			d.appendNamePersist(set, &unset, "name", node)
		} else {
			set["name"] = d.name
		}
	}
	if change.Mask&heroDaoFieldLevel != 0 {
		node := root.Child(dataengine.SyncStep{Field: 3})
		_, full := change.FullFields["level"]
		full = full || change.FullMask&heroDaoFieldLevel != 0
		if !root.Full() && node != nil && !full {
			d.appendLevelPersist(set, &unset, "level", node)
		} else {
			set["level"] = d.level
		}
	}
	if change.Mask&heroDaoFieldExp != 0 {
		node := root.Child(dataengine.SyncStep{Field: 4})
		_, full := change.FullFields["exp"]
		full = full || change.FullMask&heroDaoFieldExp != 0
		if !root.Full() && node != nil && !full {
			d.appendExpPersist(set, &unset, "exp", node)
		} else {
			set["exp"] = d.exp
		}
	}
	if change.Mask&heroDaoFieldLoginAt != 0 {
		node := root.Child(dataengine.SyncStep{Field: 5})
		_, full := change.FullFields["login_at"]
		full = full || change.FullMask&heroDaoFieldLoginAt != 0
		if !root.Full() && node != nil && !full {
			d.appendLoginAtPersist(set, &unset, "login_at", node)
		} else {
			set["login_at"] = d.loginAt
		}
	}
	if change.Mask&heroDaoFieldItems != 0 {
		node := root.Child(dataengine.SyncStep{Field: 6})
		_, full := change.FullFields["items"]
		full = full || change.FullMask&heroDaoFieldItems != 0
		if !root.Full() && node != nil && !full {
			d.appendItemsPersist(set, &unset, "items", node)
		} else {
			if full || !d.persistChangeHasPath(change, "items") {
				set["items"] = d.heroDaoItemsRawMap()
			}
		}
	}
	if change.Mask&heroDaoFieldFriends != 0 {
		node := root.Child(dataengine.SyncStep{Field: 7})
		_, full := change.FullFields["friends"]
		full = full || change.FullMask&heroDaoFieldFriends != 0
		if !root.Full() && node != nil && !full {
			d.appendFriendsPersist(set, &unset, "friends", node)
		} else {
			set["friends"] = d.friends
		}
	}
	if change.Mask&heroDaoFieldPos != 0 {
		node := root.Child(dataengine.SyncStep{Field: 8})
		_, full := change.FullFields["pos"]
		full = full || change.FullMask&heroDaoFieldPos != 0
		if !root.Full() && node != nil && !full {
			d.appendPosPersist(set, &unset, "pos", node)
		} else {
			set["pos"] = d.pos.bsonDoc()
		}
	}
	if change.Mask&heroDaoFieldEquips != 0 {
		node := root.Child(dataengine.SyncStep{Field: 9})
		_, full := change.FullFields["equips"]
		full = full || change.FullMask&heroDaoFieldEquips != 0
		if !root.Full() && node != nil && !full {
			d.appendEquipsPersist(set, &unset, "equips", node)
		} else {
			if full || !d.persistChangeHasPath(change, "equips") {
				set["equips"] = daoMapDocs(d.heroDaoEquipsRawMap(), equipInfoPtrBSONDoc)
			}
		}
	}
	if change.Mask&heroDaoFieldSquad != 0 {
		node := root.Child(dataengine.SyncStep{Field: 10})
		_, full := change.FullFields["squad"]
		full = full || change.FullMask&heroDaoFieldSquad != 0
		if !root.Full() && node != nil && !full {
			d.appendSquadPersist(set, &unset, "squad", node)
		} else {
			set["squad"] = daoSliceDocs(d.squad, equipInfoPtrBSONDoc)
		}
	}
	if change.Mask&heroDaoFieldMount != 0 {
		node := root.Child(dataengine.SyncStep{Field: 11})
		_, full := change.FullFields["mount"]
		full = full || change.FullMask&heroDaoFieldMount != 0
		if !root.Full() && node != nil && !full {
			d.appendMountPersist(set, &unset, "mount", node)
		} else {
			set["mount"] = equipInfoPtrBSONDoc(d.mount)
		}
	}
	for path, value := range change.Set {
		if !d.persistChangePathCovered(change, path) {
			set[path] = value
		}
	}
	var raw []byte
	if len(set) != 0 {
		keys := make([]string, 0, len(set))
		for path := range set {
			keys = append(keys, path)
		}
		sort.Strings(keys)
		doc := make(bson.D, 0, len(keys))
		for _, path := range keys {
			doc = append(doc, bson.E{Key: path, Value: set[path]})
		}
		var err error
		raw, err = bson.Marshal(doc)
		if err != nil {
			return dataengine.FieldPatch{}, err
		}
	}
	return dataengine.FieldPatch{SetBSON: raw, Unset: unset}, nil
}

