// HeroDaoSyncFields is the vocabulary for this DAO's dirty masks: which
// field each bit means, and what it is called on the wire.
//
// It exists because the bit constants themselves are unexported — a packer
// written outside this package can hand a mask to MarshalSync but cannot look
// inside it, which is fine until the game has its own client protocol and has
// to decide what changed.
//
// **Bit is stable only within this generated schema.** Anything that outlives
// the build — a stored projection, a client's cached layout — keys on Name or
// WireName. The bits are not an ABI.
func HeroDaoSyncFields() []dataengine.SyncFieldMeta {
	return []dataengine.SyncFieldMeta{
		{Name: "Name", WireName: "name", Bit: heroDaoFieldName},
		{Name: "Level", WireName: "level", Bit: heroDaoFieldLevel},
		{Name: "Exp", WireName: "exp", Bit: heroDaoFieldExp},
		{Name: "Items", WireName: "items", Bit: heroDaoFieldItems},
		{Name: "Friends", WireName: "friends", Bit: heroDaoFieldFriends},
		{Name: "Pos", WireName: "pos", Bit: heroDaoFieldPos},
		{Name: "Equips", WireName: "equips", Bit: heroDaoFieldEquips},
		{Name: "Squad", WireName: "squad", Bit: heroDaoFieldSquad},
		{Name: "Mount", WireName: "mount", Bit: heroDaoFieldMount},
	}
}

// SyncFields is the same table, reachable from a value — a packer holds the
// DAO, not the package.
func (d *HeroDao) SyncFields() []dataengine.SyncFieldMeta { return HeroDaoSyncFields() }

// MarshalSync 编码字段级 PB patch：包装存在表示本次覆盖，包含零值与空容器。
// 持久化、回滚快照仍使用 BSON。
func (d *HeroDao) MarshalSync(mask uint64) []byte {
	return d.marshalSyncPB(mask)
}

// MarshalSyncDelta 与 MarshalSync 相同，但不带实体 ID：给增量用（packer 的 PackSubjectDelta），接收端沿用基线的
// 实体 ID（生成的 Apply / ApplySync 在有基线时接受 0）。全量（PackSubjectSnapshot）仍用 MarshalSync。
func (d *HeroDao) MarshalSyncDelta(mask uint64) []byte {
	return d.marshalSyncPatch(mask, 0)
}

func (d *HeroDao) ApplySync(raw []byte) error {
	return d.applySyncPB(raw)
}

// --- Unmarshal ---

func (d *HeroDao) Unmarshal(raw []byte) error {
	var doc heroDaoPersistDoc
	if err := bson.Unmarshal(raw, &doc); err != nil {
		return err
	}
	d.setPersistDoc(doc)
	d.Init()
	return nil
}

// RestorePersisted is the single production hydration path used by the
// Data Engine aggregate repository. Schema must match before decoding or changing the tracker.
// A stored key heroDaoPersistDoc does not declare is reported (once per key per
// process) and the document still loads without it: the value is not read,
// and the next full write of the document drops the key (DESIGN-TODO D13).
func (d *HeroDao) RestorePersisted(raw []byte, schemaVersion uint32, version uint64) error {
	if schemaVersion != HeroDaoSchemaVersion {
		return fmt.Errorf("%w: dao HeroDao stored=%d runtime=%d", dataengine.ErrSchemaMismatch, schemaVersion, HeroDaoSchemaVersion)
	}
	heroDaoStoredKeys.WarnUnknown(raw)
	if err := d.Unmarshal(raw); err != nil {
		return err
	}
	d.tracker.SetVersion(version)
	d.CleanDirty()
	return nil
}

